import{_ as d,c as r,a,o as h}from"./app-C_dHcy8Q.js";const s={};function n(e,t){return h(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="游戏指标全景图" tabindex="-1"><a class="header-anchor" href="#游戏指标全景图"><span>游戏指标全景图</span></a></h1><p>本文档提供了完整的游戏数据指标体系，涵盖了从用户获取到长期运营的各个环节。</p><h2 id="🎯-指标分类体系" tabindex="-1"><a class="header-anchor" href="#🎯-指标分类体系"><span>🎯 指标分类体系</span></a></h2><h3 id="一、基础指标层-foundation-metrics" tabindex="-1"><a class="header-anchor" href="#一、基础指标层-foundation-metrics"><span>一、基础指标层 (Foundation Metrics)</span></a></h3><blockquote><p><strong>适用范围</strong>: 所有类型游戏必须收集的核心指标</p></blockquote><h4 id="_1-1-用户活跃与留存" tabindex="-1"><a class="header-anchor" href="#_1-1-用户活跃与留存"><span>1.1 用户活跃与留存</span></a></h4><table><thead><tr><th>指标名称</th><th>定义</th><th>计算公式</th><th>数据来源</th><th>更新频率</th></tr></thead><tbody><tr><td><strong>DAU</strong></td><td>日活跃用户数</td><td>当日有游戏行为的独立用户数</td><td>服务器登录日志</td><td>实时</td></tr><tr><td><strong>MAU</strong></td><td>月活跃用户数</td><td>当月有游戏行为的独立用户数</td><td>服务器登录日志</td><td>每日</td></tr><tr><td><strong>WAU</strong></td><td>周活跃用户数</td><td>当周有游戏行为的独立用户数</td><td>服务器登录日志</td><td>每日</td></tr><tr><td><strong>D1留存</strong></td><td>次日留存率</td><td>注册后第2天登录用户数 / 注册用户数</td><td>用户行为日志</td><td>每日</td></tr><tr><td><strong>D7留存</strong></td><td>7日留存率</td><td>注册后第8天登录用户数 / 注册用户数</td><td>用户行为日志</td><td>每周</td></tr><tr><td><strong>D30留存</strong></td><td>30日留存率</td><td>注册后第31天登录用户数 / 注册用户数</td><td>用户行为日志</td><td>每月</td></tr><tr><td><strong>DAU/MAU</strong></td><td>用户活跃度</td><td>DAU / MAU * 100%</td><td>计算指标</td><td>每日</td></tr></tbody></table><h4 id="_1-2-会话指标" tabindex="-1"><a class="header-anchor" href="#_1-2-会话指标"><span>1.2 会话指标</span></a></h4><table><thead><tr><th>指标名称</th><th>定义</th><th>计算公式</th><th>数据来源</th><th>业务价值</th></tr></thead><tbody><tr><td><strong>平均会话时长</strong></td><td>单次游戏时长</td><td>总游戏时长 / 会话数</td><td>客户端+服务器</td><td>用户粘性度量</td></tr><tr><td><strong>会话频次</strong></td><td>日均会话数</td><td>总会话数 / DAU</td><td>服务器日志</td><td>使用频率分析</td></tr><tr><td><strong>会话深度</strong></td><td>会话内行为数量</td><td>操作次数 / 会话数</td><td>客户端事件</td><td>参与度分析</td></tr></tbody></table><h4 id="_1-3-技术质量指标" tabindex="-1"><a class="header-anchor" href="#_1-3-技术质量指标"><span>1.3 技术质量指标</span></a></h4><table><thead><tr><th>指标名称</th><th>定义</th><th>计算公式</th><th>数据来源</th><th>告警阈值</th></tr></thead><tbody><tr><td><strong>崩溃率</strong></td><td>应用崩溃频率</td><td>崩溃会话数 / 总会话数</td><td>客户端SDK</td><td>&gt; 1%</td></tr><tr><td><strong>ANR率</strong></td><td>应用无响应率</td><td>ANR次数 / 启动次数</td><td>客户端SDK</td><td>&gt; 0.5%</td></tr><tr><td><strong>加载时长</strong></td><td>应用启动时间</td><td>启动完成时间戳 - 启动时间戳</td><td>客户端SDK</td><td>P95 &gt; 5s</td></tr><tr><td><strong>帧率</strong></td><td>游戏运行帧率</td><td>平均FPS</td><td>客户端监控</td><td>&lt; 30fps</td></tr><tr><td><strong>内存使用</strong></td><td>游戏内存占用</td><td>峰值内存使用量</td><td>客户端监控</td><td>&gt; 80%系统内存</td></tr></tbody></table><h3 id="二、商业化指标层-monetization-metrics" tabindex="-1"><a class="header-anchor" href="#二、商业化指标层-monetization-metrics"><span>二、商业化指标层 (Monetization Metrics)</span></a></h3><blockquote><p><strong>适用范围</strong>: 付费游戏和F2P游戏的商业化分析</p></blockquote><h4 id="_2-1-付费转化指标" tabindex="-1"><a class="header-anchor" href="#_2-1-付费转化指标"><span>2.1 付费转化指标</span></a></h4><table><thead><tr><th>指标名称</th><th>定义</th><th>计算公式</th><th>数据来源</th><th>关键分析维度</th></tr></thead><tbody><tr><td><strong>ARPU</strong></td><td>平均每用户收益</td><td>总收入 / DAU</td><td>服务器支付日志</td><td>时间、渠道、地区</td></tr><tr><td><strong>ARPPU</strong></td><td>平均每付费用户收益</td><td>总收入 / 付费用户数</td><td>服务器支付日志</td><td>付费等级、游戏模式</td></tr><tr><td><strong>PUR</strong></td><td>付费率</td><td>付费用户数 / DAU * 100%</td><td>服务器支付日志</td><td>新老用户、注册时长</td></tr><tr><td><strong>LTV</strong></td><td>用户生命周期价值</td><td>累计收入 / 用户数</td><td>ML预测模型</td><td>Cohort分析</td></tr><tr><td><strong>ROI</strong></td><td>投资回报率</td><td>(收入 - 获客成本) / 获客成本</td><td>广告投放+收入数据</td><td>渠道、Campaign</td></tr></tbody></table><h4 id="_2-2-获客成本指标" tabindex="-1"><a class="header-anchor" href="#_2-2-获客成本指标"><span>2.2 获客成本指标</span></a></h4><table><thead><tr><th>指标名称</th><th>定义</th><th>计算公式</th><th>数据来源</th><th>关键场景</th></tr></thead><tbody><tr><td><strong>CPI</strong></td><td>每安装成本</td><td>广告花费 / 安装数</td><td>广告平台API</td><td>渠道优化</td></tr><tr><td><strong>CPA</strong></td><td>每获客成本</td><td>广告花费 / 注册数</td><td>广告平台API + 注册数据</td><td>渠道评估</td></tr><tr><td><strong>CAC</strong></td><td>客户获取成本</td><td>广告花费 / 付费用户数</td><td>广告平台API + 付费数据</td><td>商业化策略</td></tr><tr><td><strong>LTV/CAC</strong></td><td>价值成本比</td><td>LTV / CAC</td><td>计算指标</td><td>渠道投入决策</td></tr></tbody></table><h4 id="_2-3-商品分析指标" tabindex="-1"><a class="header-anchor" href="#_2-3-商品分析指标"><span>2.3 商品分析指标</span></a></h4><table><thead><tr><th>指标名称</th><th>定义</th><th>计算公式</th><th>数据来源</th><th>应用场景</th></tr></thead><tbody><tr><td><strong>商品转化率</strong></td><td>单品购买转化</td><td>购买次数 / 浏览次数</td><td>客户端行为 + 支付日志</td><td>商品优化</td></tr><tr><td><strong>客单价</strong></td><td>平均单次消费</td><td>总收入 / 订单数</td><td>服务器支付日志</td><td>定价策略</td></tr><tr><td><strong>复购率</strong></td><td>重复购买率</td><td>多次购买用户数 / 总付费用户数</td><td>服务器支付日志</td><td>用户价值分析</td></tr><tr><td><strong>商品生命周期</strong></td><td>商品热度持续时间</td><td>销量下降到峰值50%的天数</td><td>时间序列分析</td><td>商品规划</td></tr></tbody></table><h3 id="三、内容质量指标层-content-quality-metrics" tabindex="-1"><a class="header-anchor" href="#三、内容质量指标层-content-quality-metrics"><span>三、内容质量指标层 (Content Quality Metrics)</span></a></h3><blockquote><p><strong>适用范围</strong>: 有明确内容进度的游戏(关卡制、任务系统等)</p></blockquote><h4 id="_3-1-内容消费指标" tabindex="-1"><a class="header-anchor" href="#_3-1-内容消费指标"><span>3.1 内容消费指标</span></a></h4><table><thead><tr><th>指标名称</th><th>定义</th><th>计算公式</th><th>数据来源</th><th>设计价值</th></tr></thead><tbody><tr><td><strong>关卡完成率</strong></td><td>关卡通关比例</td><td>完成用户数 / 开始用户数</td><td>服务器进度日志</td><td>难度平衡</td></tr><tr><td><strong>平均通关时间</strong></td><td>完成关卡耗时</td><td>总通关时间 / 通关次数</td><td>服务器进度日志</td><td>时长设计</td></tr><tr><td><strong>重试次数分布</strong></td><td>关卡重试统计</td><td>各重试次数区间的用户占比</td><td>服务器进度日志</td><td>挫折感控制</td></tr><tr><td><strong>跳过率</strong></td><td>内容跳过比例</td><td>跳过次数 / 总次数</td><td>客户端事件</td><td>内容吸引力</td></tr><tr><td><strong>内容消费速度</strong></td><td>进度推进速度</td><td>完成关卡数 / 游戏天数</td><td>服务器进度日志</td><td>内容供给节奏</td></tr></tbody></table><h4 id="_3-2-任务系统指标" tabindex="-1"><a class="header-anchor" href="#_3-2-任务系统指标"><span>3.2 任务系统指标</span></a></h4><table><thead><tr><th>指标名称</th><th>定义</th><th>计算公式</th><th>数据来源</th><th>优化方向</th></tr></thead><tbody><tr><td><strong>任务完成率</strong></td><td>任务系统参与度</td><td>完成任务数 / 接取任务数</td><td>服务器任务日志</td><td>任务设计</td></tr><tr><td><strong>日常任务活跃</strong></td><td>日常参与情况</td><td>完成日常任务的用户数 / DAU</td><td>服务器任务日志</td><td>日活提升</td></tr><tr><td><strong>成就解锁率</strong></td><td>成就系统效果</td><td>解锁成就数 / 总成就数</td><td>服务器成就日志</td><td>长期目标设计</td></tr></tbody></table><h3 id="四、社交竞技指标层-social-competitive-metrics" tabindex="-1"><a class="header-anchor" href="#四、社交竞技指标层-social-competitive-metrics"><span>四、社交竞技指标层 (Social &amp; Competitive Metrics)</span></a></h3><blockquote><p><strong>适用范围</strong>: 多人游戏、竞技游戏、社交游戏</p></blockquote><h4 id="_4-1-社交行为指标" tabindex="-1"><a class="header-anchor" href="#_4-1-社交行为指标"><span>4.1 社交行为指标</span></a></h4><table><thead><tr><th>指标名称</th><th>定义</th><th>计算公式</th><th>数据来源</th><th>社交价值</th></tr></thead><tbody><tr><td><strong>好友数分布</strong></td><td>用户社交网络规模</td><td>各好友数区间的用户占比</td><td>服务器社交日志</td><td>社交设计</td></tr><tr><td><strong>公会参与率</strong></td><td>公会系统活跃度</td><td>公会成员数 / 总用户数</td><td>服务器公会日志</td><td>组织化程度</td></tr><tr><td><strong>聊天活跃度</strong></td><td>社交互动频率</td><td>发送消息数 / DAU</td><td>服务器聊天日志</td><td>社区氛围</td></tr><tr><td><strong>礼物赠送率</strong></td><td>社交互助行为</td><td>赠送礼物次数 / DAU</td><td>服务器社交日志</td><td>社交粘性</td></tr><tr><td><strong>组队频率</strong></td><td>合作游戏参与度</td><td>组队游戏次数 / 总游戏次数</td><td>服务器组队日志</td><td>合作机制效果</td></tr></tbody></table><h4 id="_4-2-竞技平衡指标" tabindex="-1"><a class="header-anchor" href="#_4-2-竞技平衡指标"><span>4.2 竞技平衡指标</span></a></h4><table><thead><tr><th>指标名称</th><th>定义</th><th>计算公式</th><th>数据来源</th><th>平衡性价值</th></tr></thead><tbody><tr><td><strong>胜率分布</strong></td><td>竞技结果分布</td><td>各胜率区间的用户占比</td><td>服务器战斗日志</td><td>匹配算法优化</td></tr><tr><td><strong>角色胜率</strong></td><td>不同角色平衡性</td><td>各角色的胜率统计</td><td>服务器战斗日志</td><td>数值平衡调整</td></tr><tr><td><strong>段位分布</strong></td><td>竞技水平分布</td><td>各段位用户数占比</td><td>服务器排名数据</td><td>晋级机制设计</td></tr><tr><td><strong>匹配质量</strong></td><td>对战平衡度</td><td>实力差距 &lt;= 5% 的对局比例</td><td>服务器匹配日志</td><td>匹配算法优化</td></tr></tbody></table><h4 id="_4-3-pvp-pve指标" tabindex="-1"><a class="header-anchor" href="#_4-3-pvp-pve指标"><span>4.3 PVP/PVE指标</span></a></h4><table><thead><tr><th>指标名称</th><th>定义</th><th>计算公式</th><th>数据来源</th><th>设计指导</th></tr></thead><tbody><tr><td><strong>PVP参与率</strong></td><td>竞技模式参与度</td><td>PVP游戏次数 / 总游戏次数</td><td>服务器游戏模式日志</td><td>竞技内容规划</td></tr><tr><td><strong>PVE偏好度</strong></td><td>单机模式偏好</td><td>PVE游戏时长 / 总游戏时长</td><td>服务器游戏模式日志</td><td>内容比例分配</td></tr><tr><td><strong>跨模式转化</strong></td><td>模式间流转</td><td>PVE→PVP转化用户数</td><td>用户行为分析</td><td>引导机制设计</td></tr></tbody></table><h3 id="五、运营活动指标层-campaign-operations-metrics" tabindex="-1"><a class="header-anchor" href="#五、运营活动指标层-campaign-operations-metrics"><span>五、运营活动指标层 (Campaign &amp; Operations Metrics)</span></a></h3><blockquote><p><strong>适用范围</strong>: 有运营活动的游戏</p></blockquote><h4 id="_5-1-活动效果指标" tabindex="-1"><a class="header-anchor" href="#_5-1-活动效果指标"><span>5.1 活动效果指标</span></a></h4><table><thead><tr><th>指标名称</th><th>定义</th><th>计算公式</th><th>数据来源</th><th>运营价值</th></tr></thead><tbody><tr><td><strong>活动参与率</strong></td><td>活动覆盖用户比例</td><td>参与活动用户数 / DAU</td><td>服务器活动日志</td><td>活动设计评估</td></tr><tr><td><strong>活动完成率</strong></td><td>活动任务完成情况</td><td>完成活动用户数 / 参与活动用户数</td><td>服务器活动日志</td><td>活动难度调整</td></tr><tr><td><strong>活动收益</strong></td><td>活动带来的额外收入</td><td>活动期间收入 - 基准收入</td><td>收入归因分析</td><td>ROI计算</td></tr><tr><td><strong>活动留存影响</strong></td><td>活动对留存的影响</td><td>参与用户留存率 - 未参与用户留存率</td><td>用户行为对比</td><td>活动效果评估</td></tr></tbody></table><h4 id="_5-2-推送营销指标" tabindex="-1"><a class="header-anchor" href="#_5-2-推送营销指标"><span>5.2 推送营销指标</span></a></h4><table><thead><tr><th>指标名称</th><th>定义</th><th>计算公式</th><th>数据来源</th><th>优化方向</th></tr></thead><tbody><tr><td><strong>推送送达率</strong></td><td>推送消息到达率</td><td>送达数 / 发送数</td><td>推送平台API</td><td>推送渠道优化</td></tr><tr><td><strong>推送打开率</strong></td><td>推送消息点击率</td><td>打开数 / 送达数</td><td>推送平台API + 客户端</td><td>内容优化</td></tr><tr><td><strong>推送转化率</strong></td><td>推送带来的行为转化</td><td>目标行为完成数 / 推送打开数</td><td>行为归因分析</td><td>推送策略优化</td></tr><tr><td><strong>推送疲劳度</strong></td><td>用户对推送的接受度下降</td><td>连续推送的打开率递减趋势</td><td>时间序列分析</td><td>推送频率控制</td></tr></tbody></table><h3 id="六、用户体验指标层-user-experience-metrics" tabindex="-1"><a class="header-anchor" href="#六、用户体验指标层-user-experience-metrics"><span>六、用户体验指标层 (User Experience Metrics)</span></a></h3><blockquote><p><strong>适用范围</strong>: 注重用户体验的游戏</p></blockquote><h4 id="_6-1-界面交互指标" tabindex="-1"><a class="header-anchor" href="#_6-1-界面交互指标"><span>6.1 界面交互指标</span></a></h4><table><thead><tr><th>指标名称</th><th>定义</th><th>计算公式</th><th>数据来源</th><th>UX优化价值</th></tr></thead><tbody><tr><td><strong>页面停留时长</strong></td><td>用户在各页面的时间分布</td><td>页面退出时间 - 页面进入时间</td><td>客户端页面追踪</td><td>信息架构优化</td></tr><tr><td><strong>按钮点击率</strong></td><td>UI元素的交互频率</td><td>点击次数 / 展示次数</td><td>客户端UI事件</td><td>界面设计优化</td></tr><tr><td><strong>操作错误率</strong></td><td>用户操作失误频率</td><td>错误操作次数 / 总操作次数</td><td>客户端交互事件</td><td>可用性改进</td></tr><tr><td><strong>功能发现率</strong></td><td>新功能被用户发现的比例</td><td>使用新功能用户数 / 总用户数</td><td>客户端功能使用</td><td>引导设计优化</td></tr></tbody></table><h4 id="_6-2-性能体验指标" tabindex="-1"><a class="header-anchor" href="#_6-2-性能体验指标"><span>6.2 性能体验指标</span></a></h4><table><thead><tr><th>指标名称</th><th>定义</th><th>计算公式</th><th>数据来源</th><th>性能优化价值</th></tr></thead><tbody><tr><td><strong>响应延迟</strong></td><td>操作响应时间</td><td>响应完成时间 - 操作发起时间</td><td>客户端性能监控</td><td>交互体验优化</td></tr><tr><td><strong>网络质量</strong></td><td>网络连接稳定性</td><td>连接成功率、延迟分布</td><td>网络监控SDK</td><td>网络架构优化</td></tr><tr><td><strong>资源加载时间</strong></td><td>游戏资源加载效率</td><td>资源下载完成时间</td><td>客户端资源管理</td><td>资源优化策略</td></tr></tbody></table><h3 id="七、高级洞察指标层-advanced-insights-metrics" tabindex="-1"><a class="header-anchor" href="#七、高级洞察指标层-advanced-insights-metrics"><span>七、高级洞察指标层 (Advanced Insights Metrics)</span></a></h3><blockquote><p><strong>适用范围</strong>: 成熟期游戏，需要深度分析和预测</p></blockquote><h4 id="_7-1-预测性指标" tabindex="-1"><a class="header-anchor" href="#_7-1-预测性指标"><span>7.1 预测性指标</span></a></h4><table><thead><tr><th>指标名称</th><th>定义</th><th>计算模型</th><th>数据来源</th><th>预测价值</th></tr></thead><tbody><tr><td><strong>流失风险评分</strong></td><td>用户流失可能性预测</td><td>机器学习分类模型</td><td>用户行为特征</td><td>流失干预</td></tr><tr><td><strong>LTV预测</strong></td><td>用户未来价值预估</td><td>时间序列预测模型</td><td>历史付费行为</td><td>用户分群运营</td></tr><tr><td><strong>病毒系数(K因子)</strong></td><td>用户传播效果</td><td>邀请成功数 / 活跃用户数</td><td>社交分享数据</td><td>增长策略优化</td></tr></tbody></table><h4 id="_7-2-用户细分指标" tabindex="-1"><a class="header-anchor" href="#_7-2-用户细分指标"><span>7.2 用户细分指标</span></a></h4><table><thead><tr><th>指标名称</th><th>定义</th><th>分析方法</th><th>数据来源</th><th>运营应用</th></tr></thead><tbody><tr><td><strong>用户价值分层</strong></td><td>RFM模型用户分群</td><td>最近性、频率、货币价值聚类</td><td>用户行为+付费数据</td><td>精准营销</td></tr><tr><td><strong>游戏偏好分析</strong></td><td>用户游戏行为模式</td><td>聚类分析</td><td>游戏行为日志</td><td>个性化推荐</td></tr><tr><td><strong>生命周期阶段</strong></td><td>用户所处的游戏阶段</td><td>规则引擎+行为特征</td><td>综合用户数据</td><td>分阶段运营</td></tr></tbody></table><h4 id="_7-3-市场洞察指标" tabindex="-1"><a class="header-anchor" href="#_7-3-市场洞察指标"><span>7.3 市场洞察指标</span></a></h4><table><thead><tr><th>指标名称</th><th>定义</th><th>分析方法</th><th>数据来源</th><th>商业价值</th></tr></thead><tbody><tr><td><strong>NPS净推荐值</strong></td><td>用户推荐意愿</td><td>(推荐者% - 贬损者%) * 100</td><td>用户调研数据</td><td>品牌健康度</td></tr><tr><td><strong>用户满意度</strong></td><td>用户对游戏的满意程度</td><td>调研问卷+行为数据</td><td>多维度用户反馈</td><td>产品改进方向</td></tr><tr><td><strong>竞品对比</strong></td><td>相对市场地位</td><td>第三方数据对比分析</td><td>外部数据源</td><td>战略决策支持</td></tr></tbody></table><h2 id="🎮-游戏类型指标适配矩阵" tabindex="-1"><a class="header-anchor" href="#🎮-游戏类型指标适配矩阵"><span>🎮 游戏类型指标适配矩阵</span></a></h2><h3 id="休闲游戏-casual-games" tabindex="-1"><a class="header-anchor" href="#休闲游戏-casual-games"><span>休闲游戏 (Casual Games)</span></a></h3><p><strong>核心关注</strong>: 快速上手、高频使用、广告变现</p><table><thead><tr><th>优先级</th><th>指标类别</th><th>关键指标</th><th>特殊考虑</th></tr></thead><tbody><tr><td>P0</td><td>留存转化</td><td>D1/D3/D7留存、会话时长</td><td>碎片化时长分布</td></tr><tr><td>P0</td><td>广告变现</td><td>广告展示率、eCPM、广告疲劳度</td><td>平衡用户体验</td></tr><tr><td>P1</td><td>内容消费</td><td>关卡完成率、重试次数</td><td>上手难度曲线</td></tr><tr><td>P2</td><td>社交传播</td><td>分享率、邀请转化</td><td>病毒传播机制</td></tr></tbody></table><h3 id="重度rpg-heavy-rpg" tabindex="-1"><a class="header-anchor" href="#重度rpg-heavy-rpg"><span>重度RPG (Heavy RPG)</span></a></h3><p><strong>核心关注</strong>: 深度养成、长期付费、社交互动</p><table><thead><tr><th>优先级</th><th>指标类别</th><th>关键指标</th><th>特殊考虑</th></tr></thead><tbody><tr><td>P0</td><td>付费深度</td><td>ARPU、ARPPU、LTV</td><td>付费路径分析</td></tr><tr><td>P0</td><td>成长体系</td><td>升级速度、数值平衡</td><td>成长满足感</td></tr><tr><td>P1</td><td>社交粘性</td><td>公会活跃、组队频率</td><td>社交依赖度</td></tr><tr><td>P2</td><td>内容消耗</td><td>副本完成时间、PVE偏好</td><td>内容产出节奏</td></tr></tbody></table><h3 id="竞技游戏-competitive-games" tabindex="-1"><a class="header-anchor" href="#竞技游戏-competitive-games"><span>竞技游戏 (Competitive Games)</span></a></h3><p><strong>核心关注</strong>: 公平竞技、技能成长、电竞生态</p><table><thead><tr><th>优先级</th><th>指标类别</th><th>关键指标</th><th>特殊考虑</th></tr></thead><tbody><tr><td>P0</td><td>竞技平衡</td><td>胜率分布、角色平衡</td><td>公平性维护</td></tr><tr><td>P0</td><td>匹配质量</td><td>匹配时间、实力差距</td><td>竞技体验</td></tr><tr><td>P1</td><td>技能成长</td><td>段位晋升、操作提升</td><td>成就感设计</td></tr><tr><td>P2</td><td>观赛生态</td><td>观战时长、分享传播</td><td>电竞价值</td></tr></tbody></table><h3 id="策略游戏-strategy-games" tabindex="-1"><a class="header-anchor" href="#策略游戏-strategy-games"><span>策略游戏 (Strategy Games)</span></a></h3><p><strong>核心关注</strong>: 策略深度、决策分析、META演化</p><table><thead><tr><th>优先级</th><th>指标类别</th><th>关键指标</th><th>特殊考虑</th></tr></thead><tbody><tr><td>P0</td><td>策略深度</td><td>决策分支、策略成功率</td><td>策略多样性</td></tr><tr><td>P0</td><td>时间投入</td><td>思考时间、单局时长</td><td>策略复杂度平衡</td></tr><tr><td>P1</td><td>学习曲线</td><td>高级策略采用率</td><td>新手友好度</td></tr><tr><td>P2</td><td>META分析</td><td>流行策略变化趋势</td><td>版本平衡调整</td></tr></tbody></table><h2 id="📊-指标实施优先级建议" tabindex="-1"><a class="header-anchor" href="#📊-指标实施优先级建议"><span>📊 指标实施优先级建议</span></a></h2><h3 id="阶段一-基础数据建设-1-2个月" tabindex="-1"><a class="header-anchor" href="#阶段一-基础数据建设-1-2个月"><span>阶段一：基础数据建设 (1-2个月)</span></a></h3><p><strong>目标</strong>: 建立数据收集基础，覆盖核心业务指标</p><ul><li>✅ <strong>用户活跃指标</strong>: DAU/MAU、留存率</li><li>✅ <strong>技术质量指标</strong>: 崩溃率、性能指标</li><li>✅ <strong>基础商业化指标</strong>: 收入、付费率</li><li>✅ <strong>内容基础指标</strong>: 关卡完成率</li></ul><h3 id="阶段二-深化分析能力-2-4个月" tabindex="-1"><a class="header-anchor" href="#阶段二-深化分析能力-2-4个月"><span>阶段二：深化分析能力 (2-4个月)</span></a></h3><p><strong>目标</strong>: 增强分析维度，支持精细化运营</p><ul><li>📊 <strong>多维度分解</strong>: 渠道、地域、设备分析</li><li>📊 <strong>用户分群</strong>: RFM分析、行为聚类</li><li>📊 <strong>运营活动</strong>: 活动效果、推送分析</li><li>📊 <strong>竞技社交</strong>: PVP分析、社交网络</li></ul><h3 id="阶段三-智能化洞察-4-6个月" tabindex="-1"><a class="header-anchor" href="#阶段三-智能化洞察-4-6个月"><span>阶段三：智能化洞察 (4-6个月)</span></a></h3><p><strong>目标</strong>: AI驱动的预测分析和自动化决策</p><ul><li>🤖 <strong>预测模型</strong>: 流失预警、LTV预测</li><li>🤖 <strong>推荐系统</strong>: 个性化内容推荐</li><li>🤖 <strong>自动优化</strong>: 动态平衡、智能推送</li><li>🤖 <strong>竞品分析</strong>: 市场地位分析</li></ul><h2 id="💡-实施建议" tabindex="-1"><a class="header-anchor" href="#💡-实施建议"><span>💡 实施建议</span></a></h2><h3 id="数据质量保障" tabindex="-1"><a class="header-anchor" href="#数据质量保障"><span>数据质量保障</span></a></h3><ol><li><strong>数据一致性</strong>: 统一定义，避免指标歧义</li><li><strong>数据准确性</strong>: 多源校验，异常值检测</li><li><strong>数据时效性</strong>: 实时计算关键指标，T+1批处理深度分析</li><li><strong>数据完整性</strong>: 缺失值处理，数据血缘管理</li></ol><h3 id="性能优化策略" tabindex="-1"><a class="header-anchor" href="#性能优化策略"><span>性能优化策略</span></a></h3><ol><li><strong>分层存储</strong>: 热数据Redis缓存，冷数据ClickHouse存储</li><li><strong>合理采样</strong>: 根据指标重要性调整采样率</li><li><strong>预聚合</strong>: 常用维度提前计算，减少查询延迟</li><li><strong>增量计算</strong>: 基于时间窗口的增量更新机制</li></ol><hr><blockquote><p>📝 <strong>注意</strong>: 不同游戏类型应根据业务特点选择合适的指标子集，避免过度收集导致的性能问题和分析复杂度。建议从基础指标开始，逐步扩展到高级分析功能。</p></blockquote>',83)])])}const g=d(s,[["render",n]]),i=JSON.parse('{"path":"/analytics/game-metrics-overview.html","title":"游戏指标全景图","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1763325744000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":2,"url":"https://github.com/cuihairu"}],"changelog":[{"hash":"0ac3783c0cafbb7e76dd3fb0484cad90c77386b8","time":1763325744000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"docs(analytics): fix unresolved links; add missing pages; harden MDX; CI link check\\\\n\\\\nfeat(analytics): add public ingestion service (cmd/analytics-ingest), Makefile targets, Dockerfiles; compose service; fix worker image\\\\n\\\\nchore(docs): adjust config to ignore node_modules in docs plugin; remove duplicate index page\\\\n\\\\nrefactor(docs): escape MDX-sensitive chars and fence YAML blocks"},{"hash":"4a34fc6eff2c8bb89788947fb513d1f35cdb4db0","time":1762731549000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"feat: 完成游戏数据分析系统全面增强"}]},"filePathRelative":"analytics/game-metrics-overview.md"}');export{g as comp,i as data};
